{
  "scenario_title": "Monthly commercial loan loss provision builds and credit allowance coverage by business segment, 2021–2024",
  "data_context": "The Credit Risk Oversight Committee at Apex Commercial Bank recorded monthly allowance allocations, provision expenses, and realized charge-offs across four core lending portfolios from January 2021 through December 2024 to evaluate CECL macroeconomic reserve adequacy during rising interest rate cycles.",
  "script": "dim(\"business_segment\", [\"Commercial Real Estate\", \"Middle Market Lending\", \"Small Business Banking\", \"Corporate Banking\"], weights=[0.30, 0.30, 0.25, 0.15], group=\"segment\")\ndim(\"risk_tier\", [\"Investment Grade\", \"Pass-Monitor\", \"Special Mention\", \"Substandard\"], weights=[0.40, 0.35, 0.15, 0.10], ordered=\"ordinal\", group=\"credit_quality\")\n\ntime(\"reporting_month\", start=\"2021-01-01\", end=\"2024-12-31\", freq=\"monthly\")\n\nmeasure(\"provision_expense\", \"clip(4.0 + {\\\"Commercial Real Estate\\\": 8.5, \\\"Middle Market Lending\\\": 4.2, \\\"Small Business Banking\\\": 3.0, \\\"Corporate Banking\\\": 1.2}[business_segment] + {\\\"Investment Grade\\\": 1.0, \\\"Pass-Monitor\\\": 3.5, \\\"Special Mention\\\": 12.0, \\\"Substandard\\\": 24.5}[risk_tier] + 0.05 * (reporting_month / 30.4) + gaussian(0, 2.0), 0.2, 50.0)\", unit=\"USD millions\", additive=True)\nmeasure(\"allowance_coverage_ratio\", \"clip(1.1 + {\\\"Commercial Real Estate\\\": 1.2, \\\"Middle Market Lending\\\": 0.6, \\\"Small Business Banking\\\": 0.9, \\\"Corporate Banking\\\": 0.2}[business_segment] + {\\\"Investment Grade\\\": 0.3, \\\"Pass-Monitor\\\": 0.9, \\\"Special Mention\\\": 2.6, \\\"Substandard\\\": 5.2}[risk_tier] + gaussian(0, 0.25), 0.5, 15.0)\", unit=\"percent\", additive=False)\nmeasure(\"net_charge_offs\", \"clip(provision_expense * 0.62 + gaussian(0, 1.5), 0.1, 40.0)\", unit=\"USD millions\", additive=True)\n\nemit(360)",
  "intents": [
    {
      "sentence": "Compare total loan loss provision expense across business lending segments",
      "columns": [
        "business_segment",
        "provision_expense"
      ],
      "aggregate": "SUM",
      "family": "comparison"
    },
    {
      "sentence": "Track the monthly progression of average allowance coverage ratios over the four-year period",
      "columns": [
        "reporting_month",
        "allowance_coverage_ratio"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Evaluate the correlation between provision expenses and net charge-offs",
      "columns": [
        "provision_expense",
        "net_charge_offs"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
